// @category GFZ
import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import ghidra.program.model.address.*;import ghidra.program.model.mem.Memory;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
public class ScanUnresolvedExactByteCloneDomains extends GhidraScript{
 static String h(Function f,Memory m)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[]b=new byte[4096];AddressRangeIterator it=f.getBody().getAddressRanges();while(it.hasNext()){AddressRange r=it.next();long rem=r.getLength();Address p=r.getMinAddress();while(rem>0){int n=(int)Math.min(rem,b.length);int g=m.getBytes(p,b,0,n);if(g!=n)throw new IOException();md.update(b,0,n);p=p.add(n);rem-=n;}}StringBuilder s=new StringBuilder();for(byte x:md.digest())s.append(String.format("%02x",x&255));return s.toString();}
 static String own(Function f){ArrayList<String>a=new ArrayList<>();for(FunctionTag t:f.getTags()){String n=t.getName();if(n.startsWith("GFZ.V120.PrimaryOwner."))a.add("OWNER:"+n.substring("GFZ.V120.PrimaryOwner.".length()));else if(n.equals("GFZ.V120.FinalNoPrimaryOwner"))a.add("FINALNO");else if(n.startsWith("GFZ.V121.CodeDomain."))a.add("DOMAIN:"+n.substring("GFZ.V121.CodeDomain.".length()));}Collections.sort(a);return String.join(",",a);}
 public void run()throws Exception{String[]a=getScriptArgs();if(a.length!=1)throw new IllegalArgumentException("out");FunctionManager fm=currentProgram.getFunctionManager();Memory mem=currentProgram.getMemory();Map<String,List<Function>> by=new HashMap<>();ArrayList<Function> un=new ArrayList<>();for(Function f:fm.getFunctions(true)){if(f.isExternal())continue;String c=own(f);String hh=h(f,mem);by.computeIfAbsent(hh,k->new ArrayList<>()).add(f);if(c.isEmpty())un.add(f);}try(PrintWriter w=new PrintWriter(new OutputStreamWriter(new FileOutputStream(a[0]),StandardCharsets.UTF_8))){w.println("entry\tname\tbody_bytes\tbyte_sha256\tclassified_clones");int n=0;for(Function f:un){String hh=h(f,mem);ArrayList<String>cs=new ArrayList<>();for(Function g:by.get(hh)){if(g==f)continue;String c=own(g);if(!c.isEmpty())cs.add(String.format("%08X[%s]{%s}",g.getEntryPoint().getOffset(),g.getName(),c));}if(!cs.isEmpty()){w.printf("%08X\t%s\t%d\t%s\t%s%n",f.getEntryPoint().getOffset(),f.getName(),f.getBody().getNumAddresses(),hh,String.join(";",cs));n++;}}println("UNRESOLVED_EXACT_BYTE_CLONE_DOMAINS_PASS total="+n);}}
}
